// --- CSS for Invisible Scrollbar ---
const InvisibleScrollbarStyle = () => (
  <style>{`
    @import url('https://fonts.googleapis.com/css2?family=Caveat&display=swap');
    .invisible-scrollbar::-webkit-scrollbar { display: none; }
    .invisible-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
  `}</style>
);

// --- HELPER COMPONENT for Radiating Lines ---
const RadiatingLines = () => (
    <svg width="100%" height="100%" viewBox="0 0 100 100" style={styles.decoLines}>
        <line x1="50" y1="50" x2="0" y2="0" stroke="#1a202c" strokeWidth="4" />
        <line x1="50" y1="50" x2="30" y2="0" stroke="#1a202c" strokeWidth="4" />
        <line x1="50" y1="50" x2="60" y2="0" stroke="#1a202c" strokeWidth="4" />
        <line x1="50" y1="50" x2="90" y2="0" stroke="#1a202c" strokeWidth="4" />
    </svg>
);


// --- NEW COMPONENT for Image Collage ---
const ImageComposition = ({ isMobile }) => {
    const containerStyle = {...styles.imageCompositionContainer, ...(isMobile ? styles.imageCompositionContainerMobile : {})};
    
    return (
        <div style={containerStyle}>
            {/* Decorative Elements */}
            <span style={{...styles.decoStar, top: '10%', left: '15%'}}>&#10022;</span>
            <span style={{...styles.decoStar, bottom: '15%', left: '5%'}}>&#10022;</span>
            <span style={styles.decoSquiggle}>lee</span>
            <RadiatingLines />

            {/* Image 1 (Center) */}
            <div style={{...styles.imageWrapper, ...styles.imgWrap1}}>
                <img src={profileImage1} alt="Team member 1" style={styles.compositionImage} />
            </div>

            {/* Image 2 (Top Right) */}
            <div style={{...styles.imageWrapper, ...styles.imgWrap2}}>
                <img src={profileImage2} alt="Team member 2" style={styles.compositionImage} />
            </div>

            {/* Image 3 (Bottom Right) */}
            <div style={{...styles.imageWrapper, ...styles.imgWrap3}}>
                <img src={profileImage3} alt="Team member 3" style={styles.compositionImage} />
            </div>
        </div>
    );
};


// --- MODAL COMPONENT ---
const Modal = ({ isOpen, onClose, children, isMobile }) => {
  if (!isOpen) return null;
  const dynamicModalContentStyle = { ...styles.modalContent, ...(isMobile ? styles.modalContentMobile : {}) };
  return (
    <div style={styles.modalBackdrop} onClick={onClose}>
      <div style={dynamicModalContentStyle} onClick={(e) => e.stopPropagation()} className={isMobile ? 'invisible-scrollbar' : ''}>
        <button style={styles.closeButton} onClick={onClose}>&times;</button>
        {children}
      </div>
    </div>
  );
};


// --- MAIN COMPONENT ---
const AboutUs = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const openModal = () => setIsModalOpen(true);
  const closeModal = () => setIsModalOpen(false);

  // Combine styles for different states and screen sizes
  const combinedButtonStyle = { ...styles.button, ...(isHovered ? styles.buttonHover : {}) };
  const dynamicContainerStyle = { ...styles.container, ...(isMobile ? styles.containerMobile : {}) };
  const dynamicMainContentStyle = { ...styles.mainContent, ...(isMobile ? styles.mainContentMobile : {}) };
  const dynamicTitleStyle = { ...styles.title, ...(isMobile ? styles.titleMobile : {}) };
  const dynamicModalTextColumnStyle = { ...styles.modalTextColumn, ...(isMobile ? styles.modalTextColumnMobile : {}) };

  const renderParagraphs = (text) => text.split('\n\n').map((p, i) => <p key={i} style={styles.textParagraph}>{p.trim()}</p>);

  return (
    <>
      <InvisibleScrollbarStyle /> {/* Inject CSS & Google Font */}
      <div style={dynamicContainerStyle}>
        <div style={styles.titleContainer}>
          <h1 style={dynamicTitleStyle}>
            About Dietitian Karpagam
            <div style={styles.titleUnderline}></div>
          </h1>
        </div>
        
        <div style={dynamicMainContentStyle}>
          <div style={styles.textColumn}>
            <p style={styles.textParagraph}>{shortBio.trim()}</p>
            <p style={styles.textParagraph}>If you’re ready to eat better, feel better, and live better —</p>
            <blockquote style={styles.quote}>"Wellness doesn’t begin in the lab or gym — it begins on your plate."</blockquote>
            <button style={combinedButtonStyle} onClick={openModal} onMouseEnter={() => setIsHovered(true)} onMouseLeave={() => setIsHovered(false)}>
              Know More About Me →
            </button>
          </div>

          {/* Replaced the old image column with the new composition component */}
          <ImageComposition isMobile={isMobile} />
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={closeModal} isMobile={isMobile}>
        <div style={dynamicModalTextColumnStyle} className={!isMobile ? 'invisible-scrollbar' : ''}>
          {renderParagraphs(longBio)}
        </div>
        <div style={styles.modalImageColumn}>
          {/* Using a single image in the modal for simplicity */}
          <img src={profileImage1} alt="Dietitian Karpagam" style={{width: '100%', borderRadius: '12px'}} />
        </div>
      </Modal>
    </>
  );
};

export default AboutUs;
